questionvariables.text:
/*STA 141 week3 quizes*/
correct_answer:rand_selection([
[1, true, "They are not affected by extreme values"],
[2, true, "They are affected by sampling fluctuations"],
[3, true, "They are difficult to calculate"]
], 1);
incorrect_answers:rand_selection([
[4, false, "They are rigidly defined"],
[5, false, "They are based on all observations"],
[6, false, "They are calculated with reasonable ease and speed"],
[7, false, "They are easy to understand"]
], 3);
ta: random_permutation(append(correct_answer,incorrect_answers));

ta_index: sort(makelist(x[1], x, ta));
ta_largest: last(ta_index);
